// Original serialized materials, complete shader property tables and native texture
// pixels are exported from the read-only game files. Only the Windows shader's GL
// fragment program is a declared port; no material dependency is replaced by UI/Default.
// RGB24/RGBA32 and the audited DXT5 flowmap preserve their full native pixel stream
// and mip chain. Other compressed textures use decoded RGBA pixels on GL only.
#pragma warning disable CS0649
using System;using System.Collections.Generic;using System.IO;using System.Linq;
using UnityEngine;using UnityEngine.Rendering;
internal static class NativeMaterials {
 [Serializable]internal sealed class Scalar {public string name="";public float value;}
 [Serializable]internal sealed class Tint {public string name="";public float[] value=Array.Empty<float>();}
 [Serializable]internal sealed class TexEnv {public string name="",texture="";public float[] scale=Array.Empty<float>(),offset=Array.Empty<float>();}
 [Serializable]internal sealed class Property {public string name="";public int type;}
 [Serializable]internal sealed class TextureRecord {public string key="",name="";public int width,height,format,mips;}
 [Serializable]internal sealed class MaterialRecord {public string key="",name="",shader="";public int queue;public string[] keywords=Array.Empty<string>();public Scalar[] floats=Array.Empty<Scalar>();public Tint[] colors=Array.Empty<Tint>();public TexEnv[] textures=Array.Empty<TexEnv>();}
 [Serializable]internal sealed class ShaderRecord {public string key="",name="";public Property[] properties=Array.Empty<Property>();}
 [Serializable]internal sealed class Bank {public TextureRecord[] textures=Array.Empty<TextureRecord>();public MaterialRecord[] materials=Array.Empty<MaterialRecord>();public ShaderRecord[] shaders=Array.Empty<ShaderRecord>();}
 static string folder="";static Bank bank=null!;static readonly Dictionary<string,Texture2D> textures=new();static readonly Dictionary<string,Material> materials=new();static readonly List<Texture2D> duplicates=new();
 internal static void Init(string input){folder=input;bank=JsonUtility.FromJson<Bank>(File.ReadAllText(Path.Combine(folder,"native-material-list.json")));}
 internal static Material Load(string key){if(materials.TryGetValue(key,out var material))return material;var record=Array.Find(bank.materials,x=>x.key==key)??throw new Exception("Unexported native material "+key);var shader=Resources.Load<Shader>("OriginalShaders/"+record.shader);if(shader==null)throw new Exception("Original property-contract shader missing "+record.shader);shader.name=Array.Find(bank.shaders,x=>x.key==record.shader)!.name;material=new Material(shader){name=record.name,renderQueue=record.queue,shaderKeywords=record.keywords};foreach(var v in record.floats)if(material.HasProperty(v.name))material.SetFloat(v.name,v.value);foreach(var v in record.colors)if(material.HasProperty(v.name))material.SetVector(v.name,new Vector4(v.value[0],v.value[1],v.value[2],v.value[3]));foreach(var v in record.textures)if(material.HasProperty(v.name)){material.SetTexture(v.name,v.texture.Length==0?null:Texture(v.texture));material.SetTextureScale(v.name,new Vector2(v.scale[0],v.scale[1]));material.SetTextureOffset(v.name,new Vector2(v.offset[0],v.offset[1]));}materials.Add(key,material);return material;}
 static Texture2D Texture(string key){if(textures.TryGetValue(key,out var value))return value;var r=Array.Find(bank.textures,x=>x.key==key)??throw new Exception("Unexported native texture "+key);var raw=Path.Combine(folder,key+".raw");value=new Texture2D(r.width,r.height,File.Exists(raw)?(TextureFormat)r.format:TextureFormat.RGBA32,r.mips>1);if(File.Exists(raw)){value.LoadRawTextureData(File.ReadAllBytes(raw));value.Apply(false);}else{var decoded=new Texture2D(2,2);decoded.LoadImage(File.ReadAllBytes(Path.Combine(folder,key+".png")));value.SetPixels32(decoded.GetPixels32());value.Apply();UnityEngine.Object.DestroyImmediate(decoded);}value.name=r.name;textures.Add(key,value);return value;}
 internal static void AssertContract(Action<bool,string> check){check(bank.materials.Length==8&&bank.shaders.Length==5&&bank.textures.Length==14,"all original ready/results material dependencies were exported");foreach(var record in bank.materials){var m=Load(record.key);var shader=Array.Find(bank.shaders,x=>x.key==record.shader)!;check(m.shader.GetPropertyCount()==shader.properties.Length,"native shader complete property count "+record.name);for(int i=0;i<shader.properties.Length;i++)check(m.shader.GetPropertyName(i)==shader.properties[i].name&&(int)m.shader.GetPropertyType(i)==shader.properties[i].type,"native shader complete named/type contract "+record.name+"/"+shader.properties[i].name);foreach(var f in record.floats)if(m.HasProperty(f.name))check(Mathf.Approximately(m.GetFloat(f.name),f.value),"native material scalar "+record.name+"/"+f.name);foreach(var c in record.colors)if(m.HasProperty(c.name))check(m.GetVector(c.name)==new Vector4(c.value[0],c.value[1],c.value[2],c.value[3]),"native material color/vector "+record.name+"/"+c.name);foreach(var t in record.textures)if(m.HasProperty(t.name)){check(m.GetTexture(t.name)==(t.texture.Length==0?null:Texture(t.texture)),"native material texture dependency "+record.name+"/"+t.name);check(m.GetTextureScale(t.name)==new Vector2(t.scale[0],t.scale[1])&&m.GetTextureOffset(t.name)==new Vector2(t.offset[0],t.offset[1]),"native material exact texture placement "+record.name+"/"+t.name);}}
  var noise=Texture("native-texture-sharedassets1_assets-801");check(noise.width==256&&noise.height==256&&noise.format==TextureFormat.RGB24&&noise.mipmapCount==9,"native 3DNoise full descriptor matches the reported hardware dependency");var flow=Flowmap;check(flow.name=="T_flowmap_outwards_blur"&&flow.width==256&&flow.height==256&&flow.format==TextureFormat.DXT5&&flow.mipmapCount==9&&flow.GetRawTextureData().Length==87408,"native flowmap retains the reported DXT5 descriptor and entire original mip stream");}
 internal static void Cleanup(){foreach(var material in materials.Values)UnityEngine.Object.DestroyImmediate(material);foreach(var texture in textures.Values)UnityEngine.Object.DestroyImmediate(texture);foreach(var texture in duplicates)if(texture!=null)UnityEngine.Object.DestroyImmediate(texture);materials.Clear();textures.Clear();duplicates.Clear();}
 internal static Texture2D DuplicateNoise(){var source=Texture("native-texture-sharedassets1_assets-801");var copy=UnityEngine.Object.Instantiate(source);copy.name=source.name;duplicates.Add(copy);return copy;}
 internal static Texture2D Flowmap=>Texture("native-texture-resources_assets-265");
 internal static Texture2D DuplicateFlowmap(){var copy=UnityEngine.Object.Instantiate(Flowmap);copy.name=Flowmap.name;duplicates.Add(copy);return copy;}
}
// Failure scheduling port at the native Apply boundary. It does not change any
// input, material, controller or production decision; it verifies atomic rollback
// if a late Unity/widget application fails after the complete shape validation.
internal static class ResultsApplyFault {internal static bool Armed;internal static void BeforeApply(Transform root){if(Armed&&root.GetComponentInParent<Canvas>()!=null){Armed=false;throw new InvalidOperationException("scheduled native widget apply failure after validation");}}}
